('FUNDING:DISCOVER:DANI:OFFICIAL','NICHE_FUNDING_INTELLIGENCE','DANI_NICHE_FUNDING_OFFICIAL_SOURCES','P1','OPEN','Find current official sources for narrow-fit DANI DECLARES grants and capital programs, prioritizing Georgia, South Carolina and national programs with specific ownership, employer, facilities/property-services, workforce, equipment/capital or government-market eligibility.',jsonb_build_object('authority_levels',jsonb_build_array('PRIMARY','OFFICIAL'),'current_cycle_required',true,'social_only_not_sufficient',true),jsonb_build_object('entity_scope','DANI_DECLARES')),
('FUNDING:DISCOVER:SHADOW_SOL:OFFICIAL','NICHE_FUNDING_INTELLIGENCE','SHADOW_SOL_NICHE_FUNDING_OFFICIAL_SOURCES','P1','OPEN','Find current official sources for Shadow & Sol mission funding in agriculture/food systems, land stewardship, environmental education, community programming, land/facilities and access.',jsonb_build_object('authority_levels',jsonb_build_array('PRIMARY','OFFICIAL'),'current_cycle_required',true,'restricted_fund_rules_required',true),jsonb_build_object('entity_scope','SHADOW_AND_SOL')),
('FUNDING:DISCOVER:SOCIAL_REEL:20261005','NICHE_FUNDING_INTELLIGENCE','SOCIAL_GRANT_CLAIM_REVALIDATION','P1','OPEN','Find authoritative current sources for Halstead Grant, StreetShares Foundation, Kitty Fund, BOSS Impact Fund, Good Food Fund and EmpowHER and determine current/next-cycle status and exact eligibility.',jsonb_build_object('authority_levels',jsonb_build_array('PRIMARY','OFFICIAL'),'reject_stale_claims',true,'capture_next_cycle',true),jsonb_build_object('signal_origin','SOCIAL_MEDIA_USER_SUPPLIED','observed_at','2026-10-05'))
