begin;

values ('NICHE_FUNDING_INTELLIGENCE','Niche Funding & Grant Intelligence','FUNDING_CAPITAL_INTELLIGENCE','Continuously discover and revalidate narrow-fit grants, awards, capital programs and funding opportunities for DANI DECLARES and Shadow & Sol; verify social/newsletter claims against authoritative sources; preserve entity, geography, eligibility, amount, deadline and current-cycle provenance before owner review.','RESEARCHING',true,'Research only. A funding claim may reach REVIEW_READY only with current authoritative evidence for sponsor/program identity, applicant/entity eligibility, geography, award amount or range, current application status/deadline, and source provenance. Social posts and newsletters are discovery signals only. Never apply, spend, claim eligibility, contact a funder, or commingle DANI and Shadow & Sol without separate governed owner action.',jsonb_build_object('entities',jsonb_build_array('DANI_DECLARES','SHADOW_AND_SOL'),'geographies',jsonb_build_array('GEORGIA','SOUTH_CAROLINA','UNITED_STATES'),'strategy','NICHE_FIRST','source_policy','PRIMARY_OR_OFFICIAL_REQUIRED_FOR_PROMOTION','social_media_authority',false,'owner_approval_required_for_application',true,'cross_entity_commingling_authority',false,'channel_authority',jsonb_build_object('CH01','Resident Concierge','CH02','Property Management','CH03','Real Estate','CH04','Business','CH05','Government')))
on conflict(program_key) do update set program_name=excluded.program_name,domain=excluded.domain,objective=excluded.objective,status='RESEARCHING',release_blocked=true,green_rule=excluded.green_rule,metadata=coalesce(public.dd_research_programs.metadata,'{}'::jsonb)||excluded.metadata,updated_at=now();

on conflict(work_key) do update set question=excluded.question,required_evidence=excluded.required_evidence,priority=excluded.priority,status=case when public.dd_research_work_queue.status='GREEN' then public.dd_research_work_queue.status else 'QUEUED' end,blocker=null,next_action=excluded.next_action,owner_decision_required=false,metadata=coalesce(public.dd_research_work_queue.metadata,'{}'::jsonb)||excluded.metadata,updated_at=now();

on conflict(request_key) do update set request_status='OPEN',discovery_question=excluded.discovery_question,source_requirements=excluded.source_requirements,metadata=coalesce(public.dd_research_source_discovery_requests.metadata,'{}'::jsonb)||excluded.metadata,updated_at=now();

commit;
